parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "invoiceNumber": {
      "type": "string",
      "description": "Invoice number or ID EXACTLY as found on the invoice. MUST NOT be guessed, generated, inferred, or modified. Leave empty string if not present."
    },
    "invoiceDate": {
      "type": "string",
      "description": "Invoice issue date EXACTLY as written on the invoice (YYYY-MM-DD). MUST NOT be guessed or inferred. Leave empty string if missing."
    },
    "dueDate": {
      "type": "string",
      "description": "Payment due date ONLY if explicitly mentioned on the invoice (YYYY-MM-DD). MUST NOT be calculated or assumed. Leave empty string if not present."
    },
     "entry_id": {
      "type": "string",
      "description": "Bank ledger entry ID fetched from the Banking Sheet and incremented sequentially (BL-000000 format). Never guessed or modified."
    },

    "source_type": {
      "type": "string",
      "description": "Ledger source type. MUST be exactly 'Purchase' for Purhase invoices. Never guessed or changed."
    },

    "direction": {
      "type": "string",
      "description": "Direction of money flow. MUST be exactly 'OUT' for purchase payments."
    },


    "vendorName": {
      "type": "string",
      "description": "Vendor or supplier name EXACTLY as written. MUST NOT be inferred or guessed."
    },
    "vendorAddress": {
      "type": "string",
      "description": "Vendor address ONLY if explicitly present. MUST NOT be inferred. Leave empty string if missing."
    },
    "vendorPhone": {
      "type": "string",
      "description": "Vendor phone number ONLY if explicitly written. MUST NOT be guessed."
    },
    "vendorEmail": {
      "type": "string",
      "description": "Vendor email address ONLY if explicitly written. MUST NOT be guessed."
    },
    "vendorTaxId": {
      "type": "string",
      "description": "Vendor GST / Tax ID ONLY if explicitly written on the invoice. MUST NOT be inferred."
    },

    "customerName": {
      "type": "string",
      "description": "Customer or bill-to name EXACTLY as written. MUST NOT be inferred."
    },
    "customerAddress": {
      "type": "string",
      "description": "Customer address ONLY if explicitly present. MUST NOT be inferred."
    },
    "customerPhone": {
      "type": "string",
      "description": "Customer phone number ONLY if explicitly present. MUST NOT be guessed."
    },
    "customerEmail": {
      "type": "string",
      "description": "Customer email address ONLY if explicitly present. MUST NOT be guessed."
    },

    "items": {
      "type": "array",
      "description": "Line items EXACTLY as listed on the invoice. MUST NOT invent, merge, or split items.",
      "items": {
        "type": "object",
        "properties": {
          "description": {
            "type": "string",
            "description": "Item or service description EXACTLY as written. MUST NOT be inferred or summarized."
          },
          "quantity": {
            "type": "number",
            "description": "Quantity ONLY if explicitly written. MUST NOT be assumed. Use 0 if missing."
          },
          "unit": {
            "type": "string",
            "description": "Unit of measurement ONLY if explicitly mentioned (pcs, kg, hrs, etc.). Leave empty string if missing."
          },
          "unitPrice": {
            "type": "number",
            "description": "Price per unit ONLY if explicitly written. MUST NOT be calculated. Use 0 if missing."
          },
          "amount": {
            "type": "number",
            "description": "Line item total ONLY if explicitly written. MUST NOT be recalculated. Use 0 if missing."
          },
          "taxRate": {
            "type": "number",
            "description": "Tax rate ONLY if explicitly written for this item. MUST NOT be inferred. Use 0 if missing."
          }
        }
      }
    },

    "subtotal": {
      "type": "number",
      "description": "Subtotal ONLY if explicitly written on the invoice. MUST NOT be calculated. Use 0 if missing."
    },
    "taxAmount": {
      "type": "number",
      "description": "Total tax amount ONLY if explicitly written. MUST NOT be calculated. Use 0 if missing."
    },
    "taxRate": {
      "type": "number",
      "description": "Overall tax rate ONLY if explicitly written. MUST NOT be inferred. Use 0 if missing."
    },

    "discount": {
      "type": "number",
      "description": "Discount amount ONLY if explicitly written. MUST NOT be inferred or calculated. Use 0 if missing."
    },
    "discountPercentage": {
      "type": "number",
      "description": "Discount percentage ONLY if explicitly written. MUST NOT be inferred. Use 0 if missing."
    },
    "shippingCost": {
      "type": "number",
      "description": "Shipping or delivery charges ONLY if explicitly written. MUST NOT be inferred. Use 0 if missing."
    },

    "totalAmount": {
      "type": "number",
      "description": "Final total amount EXACTLY as written on the invoice. MUST NOT be recalculated or inferred."
    },
    "currency": {
      "type": "string",
      "description": "Currency code ONLY if explicitly written (INR, USD, etc.). MUST NOT be assumed."
    },

    "paymentTerms": {
      "type": "string",
      "description": "Payment terms ONLY if explicitly written (Net 30, Due on receipt, etc.). MUST NOT be inferred."
    },

    "paymentStatus": {
      "type": "string",
      "description": "Payment status derived ONLY from user caption or explicit invoice text. Allowed values: Paid, Partial, Unpaid. MUST NOT be inferred."
    },
    "paymentMethod": {
      "type": "string",
      "description": "Payment method ONLY if explicitly mentioned in user caption or invoice. MUST NOT be inferred."
    },
    "paidAmount": {
      "type": "number",
      "description": "Amount already paid ONLY if explicitly mentioned in user caption or invoice. MUST NOT be inferred or calculated. Use 0 if missing."
    },
    "remainingAmount": {
      "type": "number",
      "description": "Remaining payable amount ONLY if explicitly calculated from totalAmount − paidAmount when BOTH are available. Otherwise use 0."
    },

    "bankName": {
      "type": "string",
      "description": "Bank name ONLY if explicitly mentioned. MUST NOT be inferred."
    },
    "accountNumber": {
      "type": "string",
      "description": "Bank account number ONLY if explicitly written. MUST NOT be guessed."
    },
    "ifscCode": {
      "type": "string",
      "description": "IFSC / SWIFT code ONLY if explicitly written. MUST NOT be guessed."
    },

    "notes": {
      "type": "string",
      "description": "Additional notes ONLY if explicitly written. MUST NOT be inferred."
    },
    "status": {
      "type": "string",
      "description": "Invoice status ONLY if explicitly written (Paid, Pending, Overdue). MUST NOT be inferred."
    }
  },

  "required": [
    "invoiceNumber",
    "invoiceDate",
    "customerName",
    "items",
    "totalAmount"
  ]
}

parameters.jsCode:
// Aggregate OCR text from all pages with error handling
let aggregatedText = '';
let pageTexts = [];
let errorCount = 0;

for (const item of $input.all()) {
  try {
    // Access the correct path based on your Google Vision response
    const responses = item.json.responses?.[0]?.responses;

    if (!responses) {
      console.log('No responses found in item');
      errorCount++;
      continue;
    }

    // Loop through each page
    for (const page of responses) {
      try {
        const pageNumber = page.context?.pageNumber || pageTexts.length + 1;
        const pageText = page.fullTextAnnotation?.text || '';

        if (pageText) {
          // Store individual page text
          pageTexts.push({
            pageNumber: pageNumber,
            text: pageText,
            charCount: pageText.length
          });

          // Aggregate all text with page separator
          aggregatedText += pageText + '\n\n';
        }
      } catch (pageError) {
        console.error('Error processing page:', pageError.message);
        errorCount++;
      }
    }
  } catch (itemError) {
    console.error('Error processing item:', itemError.message);
    errorCount++;
  }
}

// Return the aggregated result
return [{
  json: {
    aggregatedText: aggregatedText.trim(),
    totalPages: pageTexts.length,
    totalCharacters: aggregatedText.length,
    pages: pageTexts,
    errors: errorCount,
    processedAt: new Date().toISOString()
  }
}];

